package finance.network;
import finance.company.*;import finance.cycle.EconomyCycleService;import finance.governance.*;import net.minecraft.network.FriendlyByteBuf;import net.minecraftforge.network.*;import java.util.*;import java.util.function.Supplier;
public record GovernanceRequestPacket(long requestId,UUID companyId){public static void encode(GovernanceRequestPacket p,FriendlyByteBuf b){b.writeLong(p.requestId);b.writeUUID(p.companyId);}public static GovernanceRequestPacket decode(FriendlyByteBuf b){return new GovernanceRequestPacket(b.readLong(),b.readUUID());}public static void handle(GovernanceRequestPacket p,Supplier<NetworkEvent.Context>s){var c=s.get();c.enqueueWork(()->{var player=c.getSender();Company company=CompanyManager.getCompany(p.companyId);if(player==null||p.requestId<=0||company==null||!company.isPublic()||!MarketDataRequestLimiter.allow(player.getUUID(),player.server.getTickCount(),"governance-data"))return;long day=EconomyCycleService.currentMcDay(player.server);var cap=ShareholderRegistryService.snapshot(p.companyId,day);var value=CompanyValuationService.calculate(company,day);var structure=CapitalStructureService.calculate(p.companyId,day);var holders=cap.holders().stream().limit(32).map(x->new GovernanceResponsePacket.HolderRow(x.id(),x.total(),x.tenderLocked(),x.ownershipPercent(),x.votingPercent())).toList();var actions=new ArrayList<GovernanceResponsePacket.ActionRow>();CorporateActionManager.buybacks().values().stream().filter(x->x.companyId().equals(p.companyId)).limit(32).forEach(x->actions.add(new GovernanceResponsePacket.ActionRow(x.id(),"BUYBACK",x.status(),x.price(),x.maxShares(),x.endDay())));CorporateActionManager.tenders().values().stream().filter(x->x.targetCompanyId().equals(p.companyId)).limit(32).forEach(x->actions.add(new GovernanceResponsePacket.ActionRow(x.id(),"TENDER",x.status(),x.price(),x.targetShares(),x.endDay())));FinancePacketHandler.CHANNEL.send(PacketDistributor.PLAYER.with(()->player),new GovernanceResponsePacket(p.requestId,p.companyId,cap.totalShares(),cap.votingShares(),cap.treasuryShares(),cap.systemLiquidity(),holders,actions,value,structure,CorporateActionManager.controllers().get(p.companyId)));});c.setPacketHandled(true);}}
